// type name[layers][rows][columns];
int a[2][3][4];                 // 2 layers, 3 rows, 4 columns = 24 elements

// initialisation: one brace pair per layer, one per row
int b[2][2][3] = {
    {{1, 2, 3}, {4, 5, 6}},     // layer 0
    {{7, 8, 9}, {10, 11, 12}}   // layer 1
};

// access: a[layer][row][column]
b[1][0][2] = 99;               // layer 1, row 0, column 2

// visit every element with three nested loops
for (int l = 0; l < 2; l++)            // layers
    for (int r = 0; r < 2; r++)        // rows
        for (int c = 0; c < 3; c++)    // columns
            cout << b[l][r][c] << " ";

