#include <iostream>
using namespace std;

int main() {
    int a[2][2][2] = {{{1, 2}, {3, 4}}, {{5, 6}, {7, 8}}};
    int total = 0;
    for (int l = 0; l < 2; l++) {
        for (int r = 0; r < 2; r++) {
            for (int c = 0; c < 2; c++) {
                total += a[l][r][c];
            }
        }
    }
    cout << "Total = " << total << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    const int TERMS = 2, STUDENTS = 3, SUBJECTS = 3;
    int marks[TERMS][STUDENTS][SUBJECTS] = {
        {{70, 65, 80}, {55, 60, 75}, {90, 85, 95}},
        {{72, 68, 78}, {60, 58, 70}, {92, 88, 97}}
    };
    for (int t = 0; t < TERMS; t++) {
        cout << "Term " << t << ":" << endl;
        for (int s = 0; s < STUDENTS; s++) {
            for (int j = 0; j < SUBJECTS; j++) {
                cout << marks[t][s][j] << " ";
            }
            cout << endl;
        }
    }
    int total = 0;
    for (int t = 0; t < TERMS; t++) {
        for (int j = 0; j < SUBJECTS; j++) {
            total += marks[t][1][j];
        }
    }
    cout << "Elements: " << TERMS * STUDENTS * SUBJECTS << endl;
    cout << "Student 1 total over both terms: " << total << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a[2][2][2];
    for (int l = 0; l < 2; l++)
        for (int r = 0; r < 2; r++)
            for (int c = 0; c < 2; c++)
                cin >> a[l][r][c];
    int big = a[0][0][0];
    int bl = 0, br = 0, bc = 0;
    for (int l = 0; l < 2; l++) {
        for (int r = 0; r < 2; r++) {
            for (int c = 0; c < 2; c++) {
                if (a[l][r][c] > big) {
                    big = a[l][r][c];
                    bl = l; br = r; bc = c;
                }
            }
        }
    }
    cout << "Largest = " << big << " at [" << bl << "][" << br << "][" << bc << "]" << endl;
    return 0;
}

