practice.answer:
for (int l = 0; l < 2; l++)
    for (int r = 0; r < 3; r++)
        for (int c = 0; c < 4; c++)
            a[l][r][c] = 0;

int sum = 0;
for (int l = 0; l < 2; l++) {
    for (int r = 0; r < 3; r++) {
        for (int c = 0; c < 4; c++) {
            sum += a[l][r][c];
        }
    }
}
